import{_ as t,a as i,b as r}from"./chunks/ai-create-03.Cig2rYP0.js";import{_ as e,o,c as n,a3 as l}from"./chunks/framework.D1iekJsc.js";const _=JSON.parse('{"title":"AI 創建角色","description":"MiniTavern 用已配置的模型寫一段描述、可選參考圖，產生角色卡；預覽裡可改欄位、保留後再創建。","frontmatter":{"title":"AI 創建角色","description":"MiniTavern 用已配置的模型寫一段描述、可選參考圖，產生角色卡；預覽裡可改欄位、保留後再創建。","head":[["meta",{"name":"keywords","content":"酒館,AI酒館,Ai酒館,迷你酒館,超迷你酒館,MiniTavern,AI夥伴,AI朋友,Ai本地聊天,Silly Tavern,SillyTavern,手機玩Silly Tavern,Silly Tavern手機版,Silly Tavern安卓,Silly Tavern蘋果,AI角色扮演,角色卡,角色扮演,AI聊天,手機AI,離線AI,AI劇情,本地大模型,本地模型,Ollama,LM Studio,世界書,正則,BYOK,使用手冊,教學,character card,AI roleplay,AI companion"}],["meta",{"property":"og:title","content":"AI 創建角色 · MiniTavern Docs"}],["meta",{"property":"og:description","content":"MiniTavern 用已配置的模型寫一段描述、可選參考圖，產生角色卡；預覽裡可改欄位、保留後再創建。"}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/zh-TW/manual/ai-create"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/zh-TW/manual/ai-create"}]]},"headers":[],"relativePath":"zh-TW/manual/ai-create.md","filePath":"zh-TW/manual/ai-create.md","lastUpdated":1791861929000}'),s={name:"zh-TW/manual/ai-create.md"};function c(g,a,h,p,d,m){return o(),n("div",null,[...a[0]||(a[0]=[l('<h1 id="ai-創建角色" tabindex="-1">AI 創建角色 <a class="header-anchor" href="#ai-創建角色" aria-label="Permalink to &quot;AI 創建角色&quot;">​</a></h1><p>路徑：底部 <strong>角色卡</strong> → <strong>創建 / 導入</strong> → <strong>AI 創建</strong>。</p><p>先配好一條 <a href="./model-link">模型連線</a> 並測連成功。沒有可用模型時不能生成，頁面會引導去配置。</p><h2 id="步驟" tabindex="-1">步驟 <a class="header-anchor" href="#步驟" aria-label="Permalink to &quot;步驟&quot;">​</a></h2><div class="shot-flow"><figure class="shot-step"><img src="'+t+'" alt="AI 創建入口"><figcaption>1 · 創建 / 導入 → AI 創建</figcaption></figure><figure class="shot-step"><img src="'+i+'" alt="填寫描述和參考圖"><figcaption>2 · 選模型、寫描述</figcaption></figure><figure class="shot-step"><img src="'+r+'" alt="預覽並創建角色"><figcaption>3 · 預覽後創建角色</figcaption></figure></div><h2 id="生成" tabindex="-1">生成 <a class="header-anchor" href="#生成" aria-label="Permalink to &quot;生成&quot;">​</a></h2><ol><li><strong>生成模型</strong>：從已經配置好的模型連線裡選一個。預設是設為預設的那條，也可以改選其它連線。</li><li><strong>描述</strong>（必填）：用一段話說明想要的角色。</li><li><strong>參考圖</strong>（可選）：點圖片可以放大查看，右上角關閉圖示可以去掉。有圖時，所選模型必須支援圖片；不支援則換模型或去掉圖。</li><li>點 <strong>生成</strong>。按鈕會顯示「生成中」，這時不能再改模型、描述和參考圖。</li></ol><p>參考圖用來讓模型看人設。第一次生成成功後，這張圖會預填成 <strong>角色頭像</strong>；模型不會另外畫一張新圖。沒傳參考圖時，預覽裡要自己選一張頭像才能創建。</p><p>生成失敗會彈出說明，點「查看詳情」可看原因。取消生成不會彈出失敗說明。</p><h2 id="預覽與保留" tabindex="-1">預覽與保留 <a class="header-anchor" href="#預覽與保留" aria-label="Permalink to &quot;預覽與保留&quot;">​</a></h2><p>生成成功後進入 <strong>預覽角色卡</strong>。生成頁本身不展示角色資料。</p><ul><li>名稱、描述、標籤、性格、開場白、世界書等都可以直接改。</li><li>每個 AI 欄位旁，以及整本 <strong>世界書</strong>，都有 <strong>保留</strong>。打開後，下次重新生成不會覆蓋這一項。手改文字不會自動打開保留。</li><li>點 <strong>重新生成</strong> 會先彈出輸入框。可以寫想改的地方；留空則按原來的描述再生成。已打開「保留」的欄位和世界書不動。全部都保留時不會再發請求。</li><li>生成過程中，「重新生成」顯示載入，「創建角色」變成取消。</li><li>點 <strong>創建角色</strong> 時會有載入提示，完成後提示已創建。創建前必須有頭像、名稱和描述。</li><li>以動漫、影視等已有作品為原型時，結果裡可以帶上一本世界書。創建後卡內會保留這份設定，並複製成一本可在聊天裡使用的世界書。用法見 <a href="./lorebook">世界書</a>。</li><li>還沒創建就離開預覽，會丟掉這次草稿，回到生成頁。參考圖仍留在生成頁。</li></ul><h2 id="相關" tabindex="-1">相關 <a class="header-anchor" href="#相關" aria-label="Permalink to &quot;相關&quot;">​</a></h2><ul><li><a href="./chara-card">角色卡</a>：導入、編輯、開聊</li><li><a href="./model-link">模型連線</a>：先配好用來生成的模型</li></ul>',14)])])}const A=e(s,[["render",c]]);export{_ as __pageData,A as default};
